/* Synchronized orbit and interruptible, accessible benefit transitions. */
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
const journeyUpdate=update;
const arc=document.querySelector('.navigator-arc-progress');
const traveler=document.querySelector('.navigator-traveler');
const halo=document.querySelector('.navigator-traveler-halo');
const trailNear=document.querySelector('.trail-near');
const trailFar=document.querySelector('.trail-far');
let displayedProgress=0,targetProgress=0,orbitFrame=0,orbitReady=false,orbitDirection=1;
function pointOnArc(percent){const length=arc.getTotalLength();return arc.getPointAtLength(Math.max(0,Math.min(100,percent))/100*length)}
function placeMarker(element,percent){if(!element||!arc)return;const point=pointOnArc(percent);element.setAttribute('cx',point.x.toFixed(2));element.setAttribute('cy',point.y.toFixed(2))}
function renderOrbit(percent){displayedProgress=percent;if(!arc)return;arc.setAttribute('stroke-dasharray',`${percent.toFixed(3)} 100`);placeMarker(traveler,percent);placeMarker(halo,percent);placeMarker(trailNear,percent-orbitDirection*2.5);placeMarker(trailFar,percent-orbitDirection*5)}
function animateOrbit(next){targetProgress=next;if(orbitFrame)cancelAnimationFrame(orbitFrame);if(!orbitReady||reducedMotion.matches){orbitReady=true;renderOrbit(next);return}const from=displayedProgress,distance=Math.abs(next-from);orbitDirection=next>=from?1:-1;if(distance<.01){renderOrbit(next);return}const duration=Math.min(950,Math.max(360,420+distance*5)),start=performance.now();function frame(now){const t=Math.min(1,(now-start)/duration),ease=1-Math.pow(1-t,3);renderOrbit(from+(next-from)*ease);if(t<1)orbitFrame=requestAnimationFrame(frame);else{orbitFrame=0;renderOrbit(next)}}orbitFrame=requestAnimationFrame(frame)}
function progressForRoute(value,thresholds){const n=Math.max(0,Number(value)||0);if(n>=thresholds[4])return 100;let i=0;while(i<4&&n>=thresholds[i+1])i++;return (i+(n-thresholds[i])/(thresholds[i+1]-thresholds[i]))*25}
function progressForBudget(){const values=getSpends();return Math.max(progressForRoute(values.branding,spendThresholds.branding),progressForRoute(values.gmv,spendThresholds.gmv))}
update=function(value,format=true){const card=document.querySelector('.gauge-wrap'),previous=card?.dataset.level;journeyUpdate(value,format);animateOrbit(progressForBudget());if(previous&&previous!==card.dataset.level&&!reducedMotion.matches){const core=document.querySelector('.navigator-core');core?.getAnimations().forEach(animation=>animation.cancel());core?.animate([{filter:'brightness(.9)',scale:'.97'},{filter:'brightness(1.22)',scale:'1.045',offset:.55},{filter:'brightness(1)',scale:'1'}],{duration:620,easing:'cubic-bezier(.2,.8,.2,1)'})}};
reducedMotion.addEventListener('change',()=>{if(reducedMotion.matches){if(orbitFrame)cancelAnimationFrame(orbitFrame);orbitFrame=0;renderOrbit(targetProgress)}});
update(Number(budget.value.replace(/\D/g,''))||0);
const sectionAnimations=new Map();
const collapsingSections=new WeakSet();
function cancelSection(section){collapsingSections.delete(section);const animation=sectionAnimations.get(section);if(animation){sectionAnimations.delete(section);animation.cancel()}const content=section.querySelector('.level-content');if(content)content.style.overflow=''}
function closeSection(section){const content=section.querySelector('.level-content');if(!section.open||!content)return;cancelSection(section);if(reducedMotion.matches){section.open=false;return}const height=content.getBoundingClientRect().height;content.style.overflow='hidden';const animation=content.animate([{height:`${height}px`,opacity:1},{height:'0px',opacity:0}],{duration:300,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'});sectionAnimations.set(section,animation);collapsingSections.add(section);animation.onfinish=()=>{if(sectionAnimations.get(section)!==animation)return;sectionAnimations.delete(section);collapsingSections.delete(section);section.open=false;content.style.overflow='';animation.cancel()};animation.oncancel=()=>{if(sectionAnimations.get(section)===animation)sectionAnimations.delete(section);content.style.overflow=''}}
function animateSectionOpen(section){const content=section.querySelector('.level-content');if(!content||reducedMotion.matches)return;cancelSection(section);const height=content.getBoundingClientRect().height;content.style.overflow='hidden';const animation=content.animate([{height:'0px',opacity:0},{height:`${height}px`,opacity:1}],{duration:360,easing:'cubic-bezier(.2,.8,.2,1)'});sectionAnimations.set(section,animation);animation.onfinish=()=>{if(sectionAnimations.get(section)!==animation)return;sectionAnimations.delete(section);content.style.overflow=''};animation.oncancel=()=>{if(sectionAnimations.get(section)===animation)sectionAnimations.delete(section);content.style.overflow=''};content.querySelectorAll('.level-benefit').forEach((row,i)=>row.animate([{opacity:0,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:260,delay:Math.min(i*35,140),easing:'ease-out'}))}
revealCurrent=function(){const current=document.querySelector('.level-section.is-current');if(!current)return;document.querySelectorAll('.level-section[data-level]').forEach(section=>{if(section===current){cancelSection(section);if(!section.open)section.open=true}else if(section.open)closeSection(section)});};
document.addEventListener('click',event=>{const summary=event.target.closest('.level-section > summary');if(!summary)return;const section=summary.parentElement;if(sectionAnimations.has(section)){event.preventDefault();const wasClosing=collapsingSections.has(section);cancelSection(section);if(!wasClosing&&section.open)closeSection(section);return}if(!section.open||reducedMotion.matches)return;event.preventDefault();closeSection(section)});
document.querySelectorAll('.level-section').forEach(section=>section.addEventListener('toggle',()=>{if(section.open)animateSectionOpen(section)}));
